#include <stdio.h>

int g = 5;

int bump(void) {
    static int s = 0;
    s = s + g;
    return s;
}

int main(void) {
    int a = bump();
    int b = bump();
    g = 1;
    int c = bump();
    printf("%d %d %d\n", a, b, c);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *rooms = (int *)malloc(sizeof(int) * 3);
    if (rooms == NULL) {
        return 1;
    }
    rooms[0] = 10;
    rooms[1] = 20;
    rooms[2] = 30;
    int sum = 0;
    for (int i = 0; i < 3; i++) {
        sum = sum + rooms[i];
    }
    printf("三间仓库加起来是 %d\n", sum);
    free(rooms);
    rooms = NULL;
    return 0;
}
